package httpserver

const demoPeopleCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#172033;background:#f4f6f8;line-height:1.55;--ink:#172033;--muted:#667286;--line:#dce1e8;--surface:#fff;--accent:#2457a7;--danger:#9b3636}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#edf2f6,#f7f8fa 260px);font-size:14px}a{color:var(--accent);text-underline-offset:3px}.shell{width:min(1280px,calc(100% - 40px));margin:auto;padding:24px 0 64px}.appbar{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:18px 22px;border:1px solid var(--line);border-radius:10px 10px 0 0;background:#fff}.brand{display:flex;align-items:center;gap:12px;font-weight:800}.mark{display:grid;width:38px;height:38px;place-items:center;border-radius:8px;background:#1d3150;color:#fff}.user{font-size:13px;color:var(--muted)}.hero{display:grid;grid-template-columns:1fr auto;gap:20px;align-items:end;padding:28px 24px;border:1px solid var(--line);border-top:0;border-radius:0 0 10px 10px;background:#fff}.eyebrow{margin:0 0 5px;color:var(--accent);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}h1{margin:0 0 9px;font-size:clamp(28px,4vw,40px);line-height:1.1;letter-spacing:-.03em}h2{margin:0 0 8px;font-size:19px}h3{margin:0 0 6px;font-size:15px}.muted{color:var(--muted)}.status-chip{padding:6px 10px;border-radius:999px;background:#edf8f3;color:#1d624a;font-size:12px;font-weight:750}.guide{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.guide-step{padding:15px;border:1px solid var(--line);border-radius:8px;background:#f8fafc}.guide-step span{display:grid;width:26px;height:26px;place-items:center;margin-bottom:10px;border-radius:50%;background:#dfe9f7;color:var(--accent);font-weight:800}.guide-step p{margin:0;color:var(--muted);font-size:13px}.layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr);gap:18px;margin-top:18px}.panel{padding:21px;border:1px solid var(--line);border-radius:9px;background:#fff;box-shadow:0 4px 16px rgba(29,42,61,.035)}.panel.full{grid-column:1/-1}.section-head{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:12px}.count{padding:4px 8px;border-radius:999px;background:#eef3f8;color:#4c5c72;font-size:12px}.stack{display:grid;gap:10px}.item{display:block;padding:13px 0;border-top:1px solid #e7ebf0;text-decoration:none;color:inherit}.item:first-child{border-top:0}.item:hover strong{color:var(--accent)}.status{font-size:12px;color:var(--muted)}.tag,code{display:inline-block;padding:2px 6px;border-radius:4px;background:#edf1f5;font:12px ui-monospace,SFMono-Regular,monospace}.form-card{margin-top:16px;padding-top:16px;border-top:1px solid var(--line)}form.stack{display:grid;gap:12px}.inline{display:flex;gap:9px;align-items:end;flex-wrap:wrap}.inline>*{flex:1}.inline button{flex:0 0 auto}label{display:grid;gap:6px;color:#435065;font-size:13px;font-weight:650}input,select,textarea{width:100%;min-height:40px;padding:9px 11px;border:1px solid #bcc5d1;border-radius:6px;background:#fff;font:inherit}textarea{min-height:82px;resize:vertical}input:focus,select:focus,textarea:focus{outline:0;border-color:var(--accent);box-shadow:0 0 0 3px rgba(36,87,167,.13)}button,.button{display:inline-flex;justify-content:center;align-items:center;min-height:40px;padding:9px 14px;border:1px solid var(--accent);border-radius:6px;background:var(--accent);color:#fff;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}.secondary{background:#fff!important;border-color:#c6cfda!important;color:#435065!important}.danger{background:#fff!important;border-color:#dfb6b6!important;color:var(--danger)!important}.back{display:inline-block;margin-bottom:14px;text-decoration:none;font-weight:700}.history{opacity:.64}.page-note{margin-top:18px;padding:13px 15px;border:1px solid #d6dfeb;border-radius:7px;background:#f5f8fc;color:#4d5c70}@media(max-width:820px){.shell{width:calc(100% - 20px)}.layout,.hero,.guide{grid-template-columns:1fr}.appbar{align-items:flex-start}.panel{padding:17px}}`

const demoDashboardHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>人员与编组</title><style>` + demoPeopleCSS + `</style></head><body><main class="shell">
<header class="appbar"><div class="brand"><span class="mark">PG</span><span>BizFoundry · People &amp; Groups</span></div><div class="user">{{.Principal.DisplayName}} · {{.Principal.Provider}}</div></header>
<section class="hero"><div><p class="eyebrow">独立业务应用 · 人员和组织事实</p><h1>人员与编组</h1><p class="muted">这里维护“有哪些人、如何编组、在组内承担什么角色与能力”。登录账号与密码仍归 IAM，项目任务、合同和资金不进入本应用。</p></div><span class="status-chip">已进入工作台</span></section>
<div class="guide"><div class="guide-step"><span>1</span><h3>先建立字典</h3><p>准备组类型、组内角色和能力，例如“项目组 / 负责人 / 现场协调”。</p></div><div class="guide-step"><span>2</span><h3>登记人员与组</h3><p>人员是业务名册；Group 表示项目组、施工队或服务小组。</p></div><div class="guide-step"><span>3</span><h3>进入组内装配</h3><p>给组加入成员、分配角色与能力，最后发布可引用的名册快照。</p></div></div>
<div class="layout">
<section class="panel"><div class="section-head"><div><p class="eyebrow">Groups</p><h2>编组</h2><p class="muted">点开任一组，继续管理成员、能力和快照。</p></div></div><div class="stack">{{range .Groups}}<a class="item" href="{{$.BasePath}}/groups/{{.ID}}"><strong>{{.Name}}</strong><br><span class="status">{{.GroupTypeKey}} · {{.Status}} · revision {{.Revision}}</span></a>{{else}}<p class="muted">还没有编组。先在右侧建立组类型，再创建第一个组。</p>{{end}}</div>{{if .GroupTypes}}<div class="form-card"><h3>建立新组</h3><form method="post" action="{{.BasePath}}/groups" class="stack"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><label>组名称<input name="name" required maxlength="120" placeholder="例如：华北设计项目组"></label><label>组类型<select name="group_type_key">{{range .GroupTypes}}<option value="{{.Key}}">{{.DisplayName}}</option>{{end}}</select></label><label>用途说明<textarea name="purpose" maxlength="1000" placeholder="说明这个组为什么存在"></textarea></label><button>建立 Group</button></form></div>{{else}}<p class="page-note">当前还没有 Group Type，请先在“可配置字典”中建立一个组类型。</p>{{end}}</section>
<section class="panel"><div class="section-head"><div><p class="eyebrow">Persons</p><h2>人员名册</h2><p class="muted">Person 是业务人员事实，不等于登录账号。</p></div></div><div>{{range .Persons}}<div class="item"><strong>{{.DisplayName}}</strong> {{if .ReferenceCode}}<code>{{.ReferenceCode}}</code>{{end}}<br><span class="status">{{.Status}} · revision {{.Revision}}{{if .IAMSubjectID}} · 已关联 IAM{{end}}</span></div>{{else}}<p class="muted">还没有人员。</p>{{end}}</div><div class="form-card"><h3>登记人员</h3><form method="post" action="{{.BasePath}}/people" class="stack"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><label>显示名<input name="display_name" required maxlength="100" placeholder="例如：张三"></label><label>业务引用码（可选）<input name="reference_code" maxlength="64" placeholder="例如：EMP-001"></label><label>IAM Subject UUID（可选）<input name="iam_subject_id" placeholder="需要登录关联时再填写"></label><button>登记 Person</button></form></div></section>
<section class="panel full"><div class="section-head"><div><p class="eyebrow">Configuration</p><h2>可配置字典</h2><p class="muted">这些是客户可命名的稳定业务词汇，不把某个行业的一次性岗位写死进内核。</p></div></div><div class="stack">{{range .Definitions}}<div class="item"><span class="tag">{{.Kind}} / {{.Key}}</span> <strong>{{.DisplayName}}</strong><br><span class="status">{{.Status}} · revision {{.Revision}}</span></div>{{else}}<p class="muted">还没有字典项。建议依次建立：组类型、组内角色、能力。</p>{{end}}</div><div class="form-card"><h3>建立字典项</h3><form method="post" action="{{.BasePath}}/definitions" class="inline"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><label>种类<select name="kind"><option value="group_type">组类型</option><option value="membership_role">组内角色</option><option value="capability">能力</option></select></label><label>稳定 key<input name="key" pattern="[a-z][a-z0-9_-]{1,62}[a-z0-9]" required placeholder="project-team"></label><label>显示名<input name="display_name" required maxlength="100" placeholder="项目组"></label><label>说明<input name="description" maxlength="500"></label><button>建立配置</button></form></div></section>
</div><p class="page-note">建议的最小演示路径：建立 1 个组类型 + 2 个角色 + 1 个能力 → 登记 2 个人 → 建立 1 个组 → 进入组详情加入成员并发布快照。</p>{{if eq .Principal.Provider "template"}}<form method="post" action="{{.BasePath}}/logout" style="margin-top:18px"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><button class="secondary">退出当前会话</button></form>{{end}}</main></body></html>`

const demoGroupHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Details.Group.Name}} · 人员与编组</title><style>` + demoPeopleCSS + `</style></head><body><main class="shell"><a class="back" href="{{.BasePath}}/">← 返回人员与编组</a><header class="appbar"><div class="brand"><span class="mark">PG</span><span>Group Workspace</span></div><div class="user">revision {{.Details.Group.Revision}}</div></header><section class="hero"><div><p class="eyebrow">{{.Details.Group.GroupTypeKey}} · {{.Details.Group.Status}}</p><h1>{{.Details.Group.Name}}</h1><p class="muted">{{if .Details.Group.Purpose}}{{.Details.Group.Purpose}}{{else}}尚未填写用途说明。{{end}}</p></div><span class="status-chip">{{.Details.Group.Status}}</span></section><p class="page-note">在这里把人员加入当前组、声明组的能力，并发布固定 revision 的名册快照供其他系统引用。</p><div class="layout"><section class="panel"><h2>组内成员</h2>{{range .Details.Memberships}}<div class="item {{if eq .Status "ended"}}history{{end}}"><strong>{{.Person.DisplayName}}</strong> <span class="tag">{{.RoleKey}}</span><br><span class="status">{{.StartDate}}{{if .EndDate}} → {{.EndDate}}{{end}} · {{.Status}} · membership revision {{.Revision}}</span>{{if and (eq .Status "active") (eq $.Details.Group.Status "active")}}<form method="post" action="{{$.BasePath}}/groups/{{$.Details.Group.ID}}/memberships/{{.ID}}/role" class="inline"><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><input type="hidden" name="command_id" value="{{$.CommandID}}"><input type="hidden" name="expected_group_revision" value="{{$.Details.Group.Revision}}"><input type="hidden" name="expected_revision" value="{{.Revision}}"><label>调整角色<select name="role_key">{{range $.Roles}}<option value="{{.Key}}">{{.DisplayName}}</option>{{end}}</select></label><button class="secondary">保存</button></form><form method="post" action="{{$.BasePath}}/groups/{{$.Details.Group.ID}}/memberships/{{.ID}}/end" class="inline"><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><input type="hidden" name="command_id" value="{{$.CommandID}}"><input type="hidden" name="expected_group_revision" value="{{$.Details.Group.Revision}}"><input type="hidden" name="expected_revision" value="{{.Revision}}"><label>结束日期<input type="date" name="end_date" value="{{$.Today}}" required></label><button class="danger">结束成员关系</button></form>{{end}}</div>{{else}}<p class="muted">当前组还没有成员。</p>{{end}}{{if eq .Details.Group.Status "active"}}<div class="form-card"><h3>加入成员</h3><form method="post" action="{{.BasePath}}/groups/{{.Details.Group.ID}}/memberships" class="stack"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><input type="hidden" name="expected_revision" value="{{.Details.Group.Revision}}"><label>人员<select name="person_id">{{range .Persons}}{{if eq .Status "active"}}<option value="{{.ID}}">{{.DisplayName}}</option>{{end}}{{end}}</select></label><label>组内角色<select name="role_key">{{range .Roles}}<option value="{{.Key}}">{{.DisplayName}}</option>{{end}}</select></label><label>开始日期<input type="date" name="start_date" value="{{.Today}}" required></label><button>加入当前组</button></form></div>{{end}}</section><section class="panel"><h2>组能力</h2>{{range .Details.Capabilities}}<div class="item {{if eq .Status "ended"}}history{{end}}"><span class="tag">{{.CapabilityKey}}</span> {{.Note}}<br><span class="status">{{.StartDate}}{{if .EndDate}} → {{.EndDate}}{{end}} · {{.Status}}</span>{{if and (eq .Status "active") (eq $.Details.Group.Status "active")}}<form method="post" action="{{$.BasePath}}/groups/{{$.Details.Group.ID}}/capabilities/{{.ID}}/end" class="inline"><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><input type="hidden" name="command_id" value="{{$.CommandID}}"><input type="hidden" name="expected_group_revision" value="{{$.Details.Group.Revision}}"><input type="hidden" name="expected_revision" value="{{.Revision}}"><label>结束日期<input type="date" name="end_date" value="{{$.Today}}" required></label><button class="danger">结束能力</button></form>{{end}}</div>{{else}}<p class="muted">当前组还没有能力画像。</p>{{end}}{{if eq .Details.Group.Status "active"}}<div class="form-card"><h3>声明能力</h3><form method="post" action="{{.BasePath}}/groups/{{.Details.Group.ID}}/capabilities" class="stack"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><input type="hidden" name="expected_revision" value="{{.Details.Group.Revision}}"><label>能力<select name="capability_key">{{range .Capabilities}}<option value="{{.Key}}">{{.DisplayName}}</option>{{end}}</select></label><label>说明<input name="note" maxlength="500"></label><label>开始日期<input type="date" name="start_date" value="{{.Today}}" required></label><button>声明能力</button></form></div>{{end}}</section><section class="panel full"><h2>名册快照</h2><p class="muted">快照固定某个 Group revision，其他业务应用可以稳定引用，不会被后续成员调整静默改变。</p>{{range .Details.Snapshots}}<div class="item"><strong>revision {{.GroupRevision}}</strong><br><code>{{.SHA256}}</code><br><a href="{{$.BasePath}}/api/v1/groups/{{$.Details.Group.ID}}/snapshots/{{.GroupRevision}}">查看机器可读快照</a></div>{{else}}<p class="muted">还没有发布快照。</p>{{end}}{{if eq .Details.Group.Status "active"}}<div class="inline"><form method="post" action="{{.BasePath}}/groups/{{.Details.Group.ID}}/snapshots"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><input type="hidden" name="expected_revision" value="{{.Details.Group.Revision}}"><button>发布 revision {{.Details.Group.Revision}} 快照</button></form><form method="post" action="{{.BasePath}}/groups/{{.Details.Group.ID}}/archive"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="command_id" value="{{.CommandID}}"><input type="hidden" name="expected_revision" value="{{.Details.Group.Revision}}"><button class="danger">归档 Group</button></form></div>{{end}}</section></div></main></body></html>`
